import type {DurableContext, DurableHandler, DurableLogger, GenericEvent} from '@sanity/functions'
import type {DurableRuntimeEvent} from '../../types.js'

type RunDurableArgs = {
  context: DurableContext
  event: GenericEvent
  logger: DurableLogger
}

type DurableIO = {
  emit: (event: DurableRuntimeEvent) => void
}

export function runDurable(
  handler: DurableHandler,
  args: RunDurableArgs,
  io: DurableIO,
): Promise<unknown>
